def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    # name -> [balance, frozen]
    accounts: dict[str, list] = {}
    # Each entry is the list of (name, previous state) pairs for one successful operation.
    # previous state is None when the account did not exist before.
    history: list[list[tuple[str, tuple | None]]] = []
    rejected: list[int] = []

    def parse_amount(s: str) -> int | None:
        if s and all("0" <= c <= "9" for c in s):
            return int(s)
        return None

    def snapshot(name: str) -> tuple | None:
        if name in accounts:
            bal, frozen = accounts[name]
            return (bal, frozen)
        return None

    def restore(name: str, prev: tuple | None) -> None:
        if prev is None:
            accounts.pop(name, None)
        else:
            accounts[name] = [prev[0], prev[1]]

    def apply(parts: list[str]):
        """Return the list of changes on success, or None on failure. Mutates state only on success."""
        verb, args = parts[0], parts[1:]

        if verb == "open" and len(args) == 2:
            name, amt = args
            bal = parse_amount(amt)
            if bal is None or name in accounts:
                return None
            accounts[name] = [bal, False]
            return [(name, None)]

        if verb == "deposit" and len(args) == 2:
            name, amt = args
            v = parse_amount(amt)
            if v is None or v <= 0 or name not in accounts:
                return None
            prev = snapshot(name)
            accounts[name][0] += v
            return [(name, prev)]

        if verb == "withdraw" and len(args) == 2:
            name, amt = args
            v = parse_amount(amt)
            if v is None or v <= 0 or name not in accounts:
                return None
            if accounts[name][1] or accounts[name][0] < v:
                return None
            prev = snapshot(name)
            accounts[name][0] -= v
            return [(name, prev)]

        if verb == "transfer" and len(args) == 3:
            src, dst, amt = args
            v = parse_amount(amt)
            if v is None or v <= 0 or src == dst:
                return None
            if src not in accounts or dst not in accounts:
                return None
            if accounts[src][1] or accounts[src][0] < v:
                return None
            prev_src, prev_dst = snapshot(src), snapshot(dst)
            accounts[src][0] -= v
            accounts[dst][0] += v
            return [(src, prev_src), (dst, prev_dst)]

        if verb == "freeze" and len(args) == 1:
            name = args[0]
            if name not in accounts or accounts[name][1]:
                return None
            prev = snapshot(name)
            accounts[name][1] = True
            return [(name, prev)]

        if verb == "unfreeze" and len(args) == 1:
            name = args[0]
            if name not in accounts or not accounts[name][1]:
                return None
            prev = snapshot(name)
            accounts[name][1] = False
            return [(name, prev)]

        return None

    for i, op in enumerate(ops):
        parts = op.split(" ")

        if parts[0] == "undo" and len(parts) == 1:
            if not history:
                rejected.append(i)
                continue
            # Undo itself is never recorded, so it can never be reverted.
            for name, prev in reversed(history.pop()):
                restore(name, prev)
            continue

        changes = apply(parts)
        if changes is None:
            rejected.append(i)
        else:
            history.append(changes)

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
